pragma solidity ^0.8.13;

import {IWLD} from "./interfaces/IWLD.sol";
import {WLDImpl} from "./abstract/WLDImpl.sol";
import {ERC20Upgradeable} from "openzeppelin-upgradeable/token/ERC20/ERC20Upgradeable.sol";

contract WLDImplV1 is IWLD, WLDImpl, ERC20Upgradeable {
    struct SupplyInfo {
        uint256 timestamp;
        uint256 amount;
    }

    uint256 constant YEAR_IN_SECONDS = 31556926;
    uint256 initialSupplyCap;
    uint256 inflationCapNumerator;
    uint256 inflationCapDenominator;
    uint256 yearAgoCursor;
    SupplyInfo[] supplyHistory;

    function initialize(
        uint256 _initialSupplyCap,
        uint256 _inflationCapNumerator,
        uint256 _inflationCapDenominator
    ) public reinitializer(1) {
        __WLDImpl_init();
        __ERC20_init("Worldcoin", "WLD");

        initialSupplyCap = _initialSupplyCap;
        inflationCapNumerator = _inflationCapNumerator;
        inflationCapDenominator = _inflationCapDenominator;
        yearAgoCursor = 0;
    }

    /// @notice Mints new tokens and assigns them to the target address.
    /// @dev This function performs inflation checks. Their semantics is as follows:
    ///     * The initial supply cap is the maximum amount of tokens that can
    ///       be minted at any time, at operator's discretion.
    ///     * After the initial supply cap is reached, the inflation cap is in effect,
    ///       making sure that the total supply of tokens does not increase by more than
    ///       `1 + (inflationCapNumerator / inflationCapDenominator)` times during any
    ///       31556926 seconds (approx. 1 year) period. 
    function mint(
        address to,
        uint256 amount
    ) public virtual onlyProxy onlyOwner {
        uint256 currentTotal = totalSupply();
        uint256 newTotal = currentTotal + amount;
        if (currentTotal < initialSupplyCap) {
            // We're still in the initial phase.
            if (newTotal >= initialSupplyCap) {
                // Reaching or crossing the initial supply cap for the first
                // time. Record this with the current timestamp – for the next
                // year, this will be the amount to compare against.
                supplyHistory.push(
                    SupplyInfo(block.timestamp, initialSupplyCap)
                );
            }
            if (newTotal > initialSupplyCap) {
                // Crossing the initial supply cap. Need to check for inflation and record final amount.
                _requireInflationCap(initialSupplyCap, newTotal);
                supplyHistory.push(SupplyInfo(block.timestamp, newTotal));
            }
            // New total is still below the initial supply cap. No need to do anything else.
        } else {
            // We're already in the inflation-controls phase.
            _advanceYearAgoCursor();
            uint256 totalSupplyYearAgo = _getTotalSupplyYearAgo();
            _requireInflationCap(totalSupplyYearAgo, newTotal);
            supplyHistory.push(SupplyInfo(block.timestamp, newTotal));
        }
        _mint(to, amount);
    }

    function _requireInflationCap(
        uint256 oldTotal,
        uint256 newTotal
    ) internal view virtual onlyProxy {
        require(
            newTotal * inflationCapDenominator <=
                oldTotal * (inflationCapNumerator + inflationCapDenominator),
            "WLD: inflation cap reached"
        );
    }

    function _advanceYearAgoCursor() internal virtual onlyProxy {
        uint256 currentTimestamp = block.timestamp;
        uint256 currentPosition = yearAgoCursor;
        // Advancing the cursor until the first of:
        // * we reach the end of the array, or
        // * we reach the first timestamp such that the next timestamp is younger than a year.
        // That means that the cursor will point to the youngest timestamp that is older than a year, i.e. the supply at one year ago.
        while (
            currentPosition + 1 < supplyHistory.length &&
            supplyHistory[currentPosition + 1].timestamp + YEAR_IN_SECONDS <
            currentTimestamp
        ) {
            currentPosition += 1;
        }
        yearAgoCursor = currentPosition;
    }

    function _getTotalSupplyYearAgo()
        internal
        view
        virtual
        onlyProxy
        returns (uint256)
    {
        return supplyHistory[yearAgoCursor].amount;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.13;

import {Ownable2StepUpgradeable} from "openzeppelin-upgradeable/access/Ownable2StepUpgradeable.sol";
import {UUPSUpgradeable} from "openzeppelin-upgradeable/proxy/utils/UUPSUpgradeable.sol";

abstract contract WLDImpl is Ownable2StepUpgradeable, UUPSUpgradeable {
    function __WLDImpl_init() internal virtual onlyInitializing {
        __Ownable_init();
        __UUPSUpgradeable_init();
    }

    error CannotRenounceOwnership();

    function renounceOwnership() public view virtual override onlyOwner {
        revert CannotRenounceOwnership();
    }

    function _authorizeUpgrade(
        address newImplementation
    ) internal virtual override onlyProxy onlyOwner {
        // No body needed as `onlyOwner` handles it.
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.13;

import {IERC20Upgradeable} from "openzeppelin-upgradeable/token/ERC20/IERC20Upgradeable.sol";

interface IWLD is IERC20Upgradeable {
    function mint(address to, uint256 amount) external;
}

[
    {
        "Issue": "Potential gas-cost griefing due to unbounded `supplyHistory` array",
        "Severity": "Low",
        "Contracts": ["WLD.sol"],
        "Description": "The `supplyHistory` array tracks the supply amount at a given timestamp and is used to get the supply amount one `period` ago to check if inflation has exceeded the specified range. Each time the function `mint(...)` is called, a new `SupplyInfo` struct is created and stored in the array. 

The function `_advanceInflationPeriodCursor(...)` reads from `supplyHistory` and will loop through the contents from the current cursor until the timestamp is more than one `period` ago. It is possible for a malicious user to repeatedly mint small amounts in a single transaction to greatly increase the entries in `supplyHistory`. When one `period` of time has passed and the inflation period cursor tries to advance, it will have to loop over these entries. If enough entries have been added, the gas cost required to SLOAD each entry in the `supplyHistory` array may be enough to deter users from minting.

An attacker could combine this with the ability to mint with zero (mentioned in the finding above), to reduce gas costs while adding entries into `supplyHistory`.

It should be noted that this type of attack would be of a greater cost to the attacker than the victim, from calculations, we estimate it to be a roughly 10x reduction. I.E: It would cost the attacker 1,000,000 gas to cause a cost of 100,000 gas to the victim minter one `period` in the future. However, given that the `period` may be up to one year, changing prices in Ether and gwei-per-gas may change this to be more favorable for the attacker.",
        "Recommendation": "In the function `mint(...)` before pushing to `supplyHistory`, consider checking if the last element in the array has the same timestamp as the current block timestamp. If the timestamps are the same, then directly overwrite the supply data in the last element rather than pushing a whole new entry. This approach prevents single-transaction attacks, making an attacker only able to inflate the entries in `supplyHistory` once per block, making attack cost non-viable.

Another solution that the WorldCoin team can consider is: the array, along with its associated complexity and costs, can be eliminated by slightly modifying the requirement, as outlined below:

- **Actual Requirement:** Inflation must remain below a given threshold for any time window considered of size `_inflationCapPeriod`.

- **Alleviated Requirement:** Inflation must remain below the given threshold within predefined time windows of `_inflationCapPeriod` seconds.

The **alleviated requirement** introduces logical time blocks (currently set at one year). Within each block, inflation consistently stays within the threshold. As a result, it is only necessary to retain information about the current time block to ensure inflation remains under control.

However, this solution permits the protocol to mint the entire amount of inflation tokens at the end of the current block and mint another amount within the first second of the subsequent block, thereby breaking the invariant established in the **actual requirement**.",
    },
    {
        "Issue": "Function `mint(...)` allows a mint `amount` of zero",
        "Severity": "Info",
        "Contracts": ["WLD.sol"],
        "Description": "The function `mint(...)` is missing input validation to prevent the argument `amount` from being zero. This will lead to `newTotal` and `oldTotal` holding the same value and then passed to `_requireInflationCap(...)`, the check will always pass (as long as the inflation limit hasn't already been exceeded). On its own, this does not cause any potential issues since no tokens are minted. However, a push to `supplyHistory` is still executed, enabling the above finding to be potentially exploited at a cheaper gas cost to the attacker than if it were impossible to mint zero amounts.

We note that this function is only controllable by the `minter` address, however, if this address is a smart contract in control of minting then it may be possible for that external contract to be manipulated into executing zero-amount mints.",
        "Recommendation": "Consider adding a check to prevent the argument `amount` from being zero.",
    },
