pragma solidity ^0.7.5;
pragma abicoder v2;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {SwapRouter} from "@v3-periphery/contracts/SwapRouter.sol";

contract ApprovalSwapRouter {
    SwapRouter immutable UNISWAP_ROUTER;

    constructor(SwapRouter _UNISWAP_ROUTER) {
        UNISWAP_ROUTER = _UNISWAP_ROUTER;
    }

    function exactInputSingle(
        SwapRouter.ExactInputSingleParams calldata params
    ) external payable returns (uint256 amountOut) {
        // Approve input token
        ERC20 tokenIn = ERC20(params.tokenIn);
        tokenIn.approve(address(UNISWAP_ROUTER), type(uint256).max);

        // Execute swap
        amountOut = UNISWAP_ROUTER.exactInputSingle(params);
    }
}

// SPDX-License-Identifier: Unlicense
pragma solidity ^0.8.13;

import {ERC20} from "solmate/tokens/ERC20.sol";

contract BatchTokenTransfers{
    ERC20 immutable public WLD_TOKEN;
    // TxSitter Relayer is the only one that can call the batch function
    address immutable public owner;
    // BVI wallet that grants allowances to this contract
    address immutable public holder;

    constructor(address _wld_token_address, address _holder, address _owner) {
        WLD_TOKEN = ERC20(_wld_token_address);
        holder = _holder;
        owner = _owner;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "BatchTokenTransfers: ONLY_OWNER");
        _;
    }

    function batch(
        address[] calldata _recipients,
        uint256[] calldata _amounts
    ) onlyOwner external {
        require(
            _recipients.length == _amounts.length,
            "BatchTokenTransfers: LENGTH_MISMATCH"
        );

        for (uint256 i = 0; i < _recipients.length; i++) {
            require(WLD_TOKEN.transferFrom(holder, _recipients[i], _amounts[i]));
        }
    }
}

